<script setup lang="ts">
import AppLayout from '@/layouts/AppLayout.vue';import{Head,router,useForm}from'@inertiajs/vue3';import{computed}from'vue';
const props=defineProps<{logs:any[];templates:Record<string,string>}>();const form=useForm({recipient_name:'',phone:'',template_key:'announcement',student:'',detail:''});
const preview=computed(()=>props.templates[form.template_key]?.replace('{name}',form.recipient_name||'Nama').replace('{student}',form.student||'siswa').replace('{detail}',form.detail||'isi pesan'));
const openWhatsapp=(log:any)=>{window.open(`https://wa.me/${log.phone}?text=${encodeURIComponent(log.message)}`,'_blank','noopener');router.post(`/komunikasi/whatsapp/${log.id}/terkirim`,{},{preserveScroll:true})};
</script>
<template><Head title="WhatsApp"/><AppLayout><main class="view space-y-6"><section class="hero-card"><div><p class="eyebrow">Persiapan komunikasi</p><h1>Pesan WhatsApp</h1><p>Normalisasi nomor, gunakan template, dan tinjau pesan. Sistem tidak mengirim pesan secara otomatis.</p></div></section><div class="content-grid two-columns"><form class="panel wa-form" @submit.prevent="form.post('/komunikasi/whatsapp',{onSuccess:()=>form.reset()})"><label>Nama penerima<input v-model="form.recipient_name" required></label><label>Nomor WhatsApp<input v-model="form.phone" required placeholder="08... atau 62..."></label><label>Template<select v-model="form.template_key"><option value="attendance">Kehadiran</option><option value="announcement">Pengumuman</option><option value="reminder">Pengingat</option></select></label><label v-if="form.template_key==='attendance'">Nama siswa<input v-model="form.student"></label><label>Detail<textarea v-model="form.detail" required rows="4"></textarea></label><div class="preview"><strong>Preview</strong><p>{{ preview }}</p></div><button class="primary-button">Simpan persiapan</button></form><section class="panel log-list"><h2>Log persiapan</h2><article v-for="l in logs" :key="l.id"><strong>{{ l.recipient_name }} · +{{ l.phone }}</strong><p>{{ l.message }}</p><small>{{ l.status }} · {{ new Date(l.prepared_at).toLocaleString('id-ID') }}</small><button @click="openWhatsapp(l)">Buka WhatsApp & catat</button></article><p v-if="!logs.length">Belum ada pesan disiapkan.</p></section></div></main></AppLayout></template>
<style scoped>.wa-form,.log-list{padding:1.25rem}.wa-form{display:grid;gap:1rem}.wa-form label{display:grid;gap:.4rem}.wa-form input,.wa-form select,.wa-form textarea{border:1px solid #cbd5e1;border-radius:.65rem;padding:.65rem}.preview{padding:1rem;border-radius:.7rem;background:#f0fdf4}.log-list{display:grid;align-content:start;gap:.8rem}.log-list article{padding:.8rem;border:1px solid #e2e8f0;border-radius:.7rem}.log-list small{display:block;color:#64748b}.log-list a{color:#15803d;font-weight:700;font-size:.8rem}</style>
